//! About dialog data (M6-03): version, commit, license and the third-party
//! components shipped with the binary.

use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use git_core::identity;

/// SPDX identifier of the project license (ADR-008).
pub const LICENSE_ID: &str = "GPL-3.0-or-later";

/// Text of the GPL version 3.
pub const LICENSE_URL: &str = "https://www.gnu.org/licenses/gpl-3.0.html";

/// File name of the full third-party notices shipped with every package.
pub const NOTICES_FILE: &str = "THIRD-PARTY-LICENSES.md";

/// Compact list generated by `scripts/third-party-licenses.sh`.
const COMPONENTS: &str = include_str!("../assets/third-party.tsv");

/// Version of this build, e.g. "1.0.0-rc.1".
pub fn version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

/// Short Git commit of this build (from `build.rs`), or "unknown".
pub fn commit() -> &'static str {
    env!("BUILD_GIT_COMMIT")
}

/// One third-party component.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Component {
    pub name: &'static str,
    pub version: &'static str,
    pub license: &'static str,
}

static PARSED: LazyLock<Vec<Component>> = LazyLock::new(|| parse_components(COMPONENTS));

/// All third-party components, in the order of the generated list.
pub fn components() -> &'static [Component] {
    &PARSED
}

fn parse_components(list: &'static str) -> Vec<Component> {
    list.lines()
        .filter_map(|line| {
            let mut parts = line.split('\t');
            let name = parts.next()?.trim();
            let version = parts.next()?.trim();
            let license = parts.next()?.trim();
            (!name.is_empty()).then_some(Component {
                name,
                version,
                license,
            })
        })
        .collect()
}

/// Where the full notices are: the file shipped next to the executable (or
/// in the package's resource/doc directory), else the copy in the
/// repository for this version.
pub fn notices_target(exe: Option<&Path>) -> String {
    exe.and_then(Path::parent)
        .into_iter()
        .flat_map(notices_candidates)
        .find(|path| path.is_file())
        .map(|path| path.to_string_lossy().into_owned())
        .unwrap_or_else(|| notices_url(version()))
}

/// Package layouts (M6-08): next to the binary (zip, tar.gz, msi), the
/// macOS bundle's `Resources`, `lib/<binary>` (AppImage resources) and
/// `share/doc/<binary>`.
fn notices_candidates(dir: &Path) -> Vec<PathBuf> {
    vec![
        dir.join(NOTICES_FILE),
        dir.join("..").join("Resources").join(NOTICES_FILE),
        dir.join("..")
            .join("lib")
            .join(identity::BINARY_NAME)
            .join(NOTICES_FILE),
        dir.join("..")
            .join("share")
            .join("doc")
            .join(identity::BINARY_NAME)
            .join(NOTICES_FILE),
    ]
}

/// The notices in the repository at the tag of `version`.
pub fn notices_url(version: &str) -> String {
    format!(
        "{}/blob/v{version}/{NOTICES_FILE}",
        identity::REPOSITORY_URL
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn components_list_is_embedded_and_complete() {
        let all = components();
        assert!(all.len() > 100, "only {} components", all.len());
        assert!(all
            .iter()
            .any(|c| c.name == "iced" && c.license.contains("MIT")));
        assert!(all.iter().any(|c| c.name == "gix"));
        assert!(all
            .iter()
            .any(|c| c.name == "Lucide icons" && c.license == "ISC"));
        // Our own crates are not third-party.
        assert!(!all
            .iter()
            .any(|c| c.name == "git-core" || c.name == "git-graph"));
        assert!(all
            .iter()
            .all(|c| !c.version.is_empty() && !c.license.is_empty()));
    }

    #[test]
    fn parse_skips_incomplete_lines() {
        let parsed = parse_components("a\t1.0\tMIT\n\nbroken line\nb\t2.0\tISC\n");
        assert_eq!(parsed.len(), 2);
        assert_eq!(parsed[1].name, "b");
        assert_eq!(parsed[1].license, "ISC");
    }

    #[test]
    fn notices_are_found_next_to_the_binary_or_online() {
        let dir = tempfile::tempdir().unwrap();
        let exe = dir.path().join("bin").join("app");
        std::fs::create_dir_all(exe.parent().unwrap()).unwrap();
        // Nothing shipped: the repository copy of this version.
        assert_eq!(notices_target(Some(&exe)), notices_url(version()));
        assert!(notices_url("1.0.0").ends_with("/blob/v1.0.0/THIRD-PARTY-LICENSES.md"));
        assert_eq!(notices_target(None), notices_url(version()));

        // AppImage layout: usr/bin/<binary> and usr/share/doc/<binary>/.
        let doc = dir.path().join("share/doc").join(identity::BINARY_NAME);
        std::fs::create_dir_all(&doc).unwrap();
        std::fs::write(doc.join(NOTICES_FILE), "x").unwrap();
        assert!(notices_target(Some(&exe)).ends_with(NOTICES_FILE));
        assert!(!notices_target(Some(&exe)).starts_with("https://"));

        // Next to the binary wins.
        std::fs::write(dir.path().join("bin").join(NOTICES_FILE), "x").unwrap();
        assert_eq!(
            PathBuf::from(notices_target(Some(&exe))),
            dir.path().join("bin").join(NOTICES_FILE)
        );
    }

    #[test]
    fn commit_and_version_are_set() {
        assert!(!version().is_empty());
        assert!(!commit().is_empty());
    }
}
